import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { SimulatorParams, Statistics, GraphDataPoint } from '../components/retirement/types';
import html2canvas from 'html2canvas';

// Interface for recommendation item
interface RecommendationItem {
  change: string;
  impact: string;
  priority: string;
}

// Interface for analyses data
interface AnalysesData {
  investmentIncrease: {
    amount: number;
    additionalCapital: number;
    estimatedAdditionalReturns: number;
    totalBenefit: number;
  };
  delayRetirement: {
    years: number;
    impact: number;
    newCapital: number;
  };
  withdrawalReduction: {
    amount: number;
    totalSavings: number;
    additionalYears: number;
  };
  returnImprovement: {
    percent: number;
    benefit: number;
    newCapital: number;
  };
  runningOut: {
    risk: string;
    safetyMargin: number;
    statusClass?: string; // Optional UI-specific property
  };
  recommendations: RecommendationItem[];
}

// Extend Statistics interface with expected properties
interface ExtendedStatistics extends Statistics {
  yearToReach100k?: number;
  yearToReach250k?: number;
  yearToReach500k?: number;
  yearToReach1M?: number;
  yearFundsDeplete?: number;
  ageAtYear: (year: number) => number;
}

interface PdfGenerationOptions {
  params: SimulatorParams;
  statistics: ExtendedStatistics;
  formatAmount: (value: number) => string;
  chartRef?: React.RefObject<HTMLDivElement>;
  analyses?: AnalysesData; // Using our typed interface
  scheduleData?: GraphDataPoint[]; // Detailed schedule data from ScheduleDetails component
}

// Main function to generate and download the PDF report
export const generateRetirementReport = async ({
  params,
  statistics,
  formatAmount,
  chartRef,
  analyses,
  scheduleData
}: PdfGenerationOptions) => {
  console.log('Starting PDF generation in pdfGenerator.ts');
  
  try {
    // Create new PDF document - A4 size in portrait orientation
    console.log('Creating new jsPDF instance');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const pageWidth = pdf.internal.pageSize.getWidth();
    const pageHeight = pdf.internal.pageSize.getHeight();
    const margin = 15; // margin in mm
    const contentWidth = pageWidth - 2 * margin;
    
    // Function to add page number at the bottom of each page
    const addPageNumber = (pageNum: number) => {
      pdf.setFontSize(9);
      pdf.setTextColor(150, 150, 150);
      pdf.text(`Page ${pageNum}`, pageWidth - margin, pageHeight - 10, { align: 'right' });
    };
    
    // Add page number to first page
    addPageNumber(1);
    let currentPage = 1;
    
    // Hook into the addPage method to add page numbers automatically
    const originalAddPage = pdf.addPage.bind(pdf);
    pdf.addPage = function() {
      originalAddPage();
      currentPage++;
      addPageNumber(currentPage);
      return this;
    };
    
    console.log('Adding title section');
    // Add report title
    pdf.setFontSize(24);
    pdf.setTextColor(63, 81, 181); // Indigo color
    pdf.text('Retirement Planning Report', pageWidth / 2, margin, { align: 'center' });
    
    // Add generation date
    pdf.setFontSize(10);
    pdf.setTextColor(100, 100, 100);
    const today = new Date().toLocaleDateString(undefined, { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    });
    pdf.text(`Generated on ${today}`, pageWidth / 2, margin + 7, { align: 'center' });
    
    // Add table of contents
    let yPos = margin + 20;
    pdf.setFontSize(14);
    pdf.setTextColor(70, 70, 70);
    pdf.text('Report Contents:', margin, yPos);
    yPos += 5;
    
    // List of sections with dot leaders
    const sections = [
      'Executive Summary',
      'Detailed Results Summary',
      'Capital Projection Chart', 
      'Retirement Optimization Strategies',
      'Detailed Schedule Projection',
      'Plan Parameters',
      'Important Notes'
    ];
    
    pdf.setFontSize(11);
    pdf.setTextColor(100, 100, 100);
    
    sections.forEach((section, index) => {
      yPos += 6;
      pdf.text(section, margin, yPos);
      
      // Draw a dot leader line
      pdf.setDrawColor(200, 200, 200);
      pdf.setLineWidth(0.2);
      pdf.setLineDashPattern([0.5, 1], 0);
      pdf.line(margin + 65, yPos - 2, margin + 120, yPos - 2);
      
      // Reset dash pattern
      pdf.setLineDashPattern([], 0);
      
      // Add page indicator (we'll use placeholder "p." since actual page numbers depend on content)
      pdf.text(`p. ${index + 2}`, margin + 125, yPos);
    });
    
    // Start the content position after the TOC
    yPos += 15;
    
    console.log('Adding summary section');
    // Add bookmark for navigation in PDF viewers if supported by the library
    try {
      (pdf as any).bookmark('Executive Summary', { pageNumber: currentPage });
    } catch (e) {
      console.log('PDF bookmarks not supported in this version of jsPDF');
    }
    // Add redesigned summary section
    yPos = addSummarySection(pdf, params, statistics, formatAmount, margin, contentWidth, yPos);
    
    // Add page break if needed
    if (yPos > pageHeight - 40) {
      pdf.addPage();
      yPos = margin;
    }
    
    console.log('Adding results summary section');
    // Add bookmark for Results Summary
    try {
      (pdf as any).bookmark('Detailed Results Summary', { pageNumber: currentPage });
    } catch (e) {
      // Silently continue if bookmarks aren't supported
    }
    // Add the results summary section
    yPos = addResultsSummarySection(pdf, params, statistics, formatAmount, margin, contentWidth, yPos);
    
    // Add page break if needed
    if (yPos > pageHeight - 40) {
      pdf.addPage();
      yPos = margin;
    }
    
    console.log('Adding chart section, chartRef exists:', !!chartRef?.current);
    // Add bookmark for Capital Projection Chart
    try {
      (pdf as any).bookmark('Capital Projection Chart', { pageNumber: currentPage });
    } catch (e) {
      // Silently continue if bookmarks aren't supported
    }
    // Add chart if available
    if (chartRef?.current) {
      try {
        yPos = await addChartSection(pdf, chartRef, margin, contentWidth, yPos);
        console.log('Chart added successfully');
      } catch (chartError) {
        console.error('Error adding chart to PDF:', chartError);
      }
    }
    
    // Add page break if needed
    if (yPos > pageHeight - 60) {
      pdf.addPage();
      yPos = margin;
    }
    
    console.log('Adding analyses section');
    // Add bookmark for Analyses Section
    try {
      (pdf as any).bookmark('Retirement Optimization Strategies', { pageNumber: currentPage });
    } catch (e) {
      // Silently continue if bookmarks aren't supported
    }
    // Add analyses and optimization section
    yPos = addAnalysesSection(pdf, params, statistics, formatAmount, margin, contentWidth, yPos, analyses);
    
    // Add page break if needed
    if (yPos > pageHeight - 60) {
      pdf.addPage();
      yPos = margin;
    }
    
    console.log('Adding detailed schedule section');
    // Add bookmark for Detailed Schedule
    try {
      (pdf as any).bookmark('Detailed Schedule Projection', { pageNumber: currentPage });
    } catch (e) {
      // Silently continue if bookmarks aren't supported
    }
    // Add detailed schedule section
    if (scheduleData && scheduleData.length > 0) {
      yPos = addScheduleSection(pdf, formatAmount, margin, contentWidth, yPos, scheduleData);
      
      // Add page break if needed
      if (yPos > pageHeight - 60) {
        pdf.addPage();
        yPos = margin;
      }
    } else {
      console.log('No schedule data provided, skipping schedule section');
    }

    console.log('Adding parameters section');
    // Add bookmark for Parameters Section  
    try {
      (pdf as any).bookmark('Plan Parameters', { pageNumber: currentPage });
    } catch (e) {
      // Silently continue if bookmarks aren't supported
    }
    // Add parameters section
    yPos = addParametersSection(pdf, params, formatAmount, margin, contentWidth, yPos);
    
    // Add page break if needed
    if (yPos > pageHeight - 60) {
      pdf.addPage();
      yPos = margin;
    }
    
    console.log('Adding disclaimer section');
    // Add bookmark for Disclaimer
    try {
      (pdf as any).bookmark('Important Notes', { pageNumber: currentPage });
    } catch (e) {
      // Silently continue if bookmarks aren't supported
    }
    // Add final notes and disclaimer
    yPos = addDisclaimerSection(pdf, margin, contentWidth, yPos);
    
    console.log('Saving PDF file');
    // Save the PDF with filename
    pdf.save('Retirement-Planning-Report.pdf');
    console.log('PDF saved successfully');
  } catch (error) {
    console.error('Error in PDF generation:', error);
    throw error;
  }
};

// Helper constants for consistent colors throughout the document
const COLORS = {
  primary: [63, 81, 181] as [number, number, number],      // Main theme color - indigo
  secondary: [100, 100, 100] as [number, number, number],  // Secondary text
  success: [46, 125, 50] as [number, number, number],      // Success/positive values
  warning: [237, 108, 2] as [number, number, number],      // Warning/caution values
  danger: [211, 47, 47] as [number, number, number],       // Danger/negative values
  light: [240, 240, 255] as [number, number, number],      // Light background
  lighter: [248, 248, 255] as [number, number, number],    // Even lighter background
  highlight: [232, 245, 253] as [number, number, number],  // Highlight background - light blue
  border: [200, 200, 220] as [number, number, number]      // Border color
};

// Helper function to add consistent section headers
const addSectionHeader = (
  pdf: jsPDF, 
  title: string, 
  description: string, 
  margin: number, 
  contentWidth: number, 
  startY: number
): number => {
  let yPos = startY;
  
  // Section header
  pdf.setFontSize(16);
  pdf.setTextColor(63, 81, 181);
  pdf.text(title, margin, yPos);
  
  // Draw design element - blue line under title
  pdf.setDrawColor(63, 81, 181);
  pdf.setLineWidth(0.5);
  pdf.line(margin, yPos + 3, margin + contentWidth/4, yPos + 3);
  
  yPos += 8;
  
  // Section description
  pdf.setFontSize(10);
  pdf.setTextColor(100, 100, 100);
  pdf.text(description, margin, yPos);
  yPos += 10;
  
  return yPos;
};

// Helper function for consistent table styling
const applyTableStyle = (
  tableOptions: any, 
  type: 'primary' | 'data' | 'summary' | 'compact' = 'data'
) => {
  // Base styles
  tableOptions.headStyles = { 
    fillColor: COLORS.primary, 
    textColor: [255, 255, 255],
    fontStyle: 'bold',
    halign: 'left'
  };
  tableOptions.alternateRowStyles = { fillColor: COLORS.light };
  
  // Set theme as 'grid' which is a valid theme type
  tableOptions.theme = 'grid';
  
  // Specific styles based on table type
  if (type === 'primary') {
    tableOptions.bodyStyles = { fontSize: 11 };
    tableOptions.headStyles.fontSize = 12;
  } else if (type === 'data') {
    tableOptions.bodyStyles = { fontSize: 10 };
    tableOptions.headStyles.fontSize = 11;
  } else if (type === 'summary') {
    tableOptions.bodyStyles = { fontSize: 10, fontStyle: 'bold' };
    tableOptions.alternateRowStyles.fillColor = COLORS.highlight;
  } else if (type === 'compact') {
    tableOptions.bodyStyles = { fontSize: 9, cellPadding: 2 };
    tableOptions.headStyles.fontSize = 9;
  }
  
  return tableOptions;
};

// Add financial summary table with enhanced styling
const addFinancialTable = (
  pdf: jsPDF,
  data: string[][],
  startY: number,
  margin: number,
  width: number,
  title: string,
  type: 'primary' | 'data' | 'summary' | 'compact' = 'data'
): number => {
  // Add title
  pdf.setFontSize(14);
  pdf.setTextColor(70, 70, 70);
  pdf.text(title, margin, startY);
  
  // Configure table options
  const tableOptions = {
    startY: startY + 7,
    body: data,
    margin: { left: margin, right: margin },
    tableWidth: width
  };
  
  // Apply consistent styling
  applyTableStyle(tableOptions, type);
  
  // Draw the table
  autoTable(pdf, tableOptions);
  
  // Return the final Y position
  return (pdf as any).lastAutoTable.finalY;
};

// Add summary section to the PDF - Redesigned with columns and more visual elements
const addSummarySection = (
  pdf: jsPDF,
  params: SimulatorParams,
  statistics: ExtendedStatistics,
  formatAmount: (value: number) => string,
  margin: number,
  contentWidth: number,
  startY: number
): number => {
  let yPos = startY;
  
  // Section header - Executive Summary has a slightly different style
  pdf.setFontSize(20); // Larger font for executive summary
  pdf.setTextColor(63, 81, 181);
  pdf.text('Executive Summary', margin, yPos);
  yPos += 10;

  // Draw line under header - longer for executive summary
  pdf.setDrawColor(63, 81, 181);
  pdf.setLineWidth(0.5);
  pdf.line(margin, yPos - 5, margin + contentWidth/2, yPos - 5);
  
  // Calculate core values
  const retirementAge = typeof params.retirementInput === 'string' 
    ? parseInt(params.retirementInput, 10) 
    : params.retirementInput;
  const currentAge = params.currentAge;
  const yearsToRetirement = retirementAge - currentAge;
  const retirementCapital = statistics.capitalAtRetirement || 0;
  
  // Calculate monthly income in retirement
  let monthlyIncome = 0;
  if (params.withdrawalMode === 'amount') {
    monthlyIncome = params.monthlyRetirementWithdrawal;
  } else if (params.withdrawalMode === 'rate' && params.withdrawalRate) {
    monthlyIncome = (retirementCapital * (params.withdrawalRate / 100)) / 12;
  } else {
    // Age-based withdrawal
    const yearsInRetirement = params.maxAge - retirementAge;
    const realReturnRate = (params.annualReturnRate - params.inflation) / 100;
    monthlyIncome = calculateSustainableWithdrawal(retirementCapital, realReturnRate, yearsInRetirement);
  }
  
  // Risk assessment based on withdrawal rate
  const effectiveWithdrawalRate = retirementCapital > 0 ? (monthlyIncome * 12) / retirementCapital * 100 : 0;
  const isAtRisk = effectiveWithdrawalRate > 5;
  
  // Calculate retirement period data
  const expectedEndAge = statistics.yearFundsDeplete 
    ? statistics.ageAtYear(statistics.yearFundsDeplete)
    : params.maxAge;
  const yearsInRetirement = expectedEndAge - retirementAge;
  
  // Setup columns
  const colWidth = contentWidth / 2 - 5;
  
  // Column 1: Key Financial Data
  pdf.setFontSize(14);
  pdf.setTextColor(70, 70, 70);
  pdf.text('Key Financial Projections', margin, yPos);
  yPos += 7;
  
  // Create financial summary table
  const financialData = [
    ['Current Capital', formatAmount(params.initialCapital)],
    ['Projected Retirement Capital', formatAmount(retirementCapital)],
    ['Monthly Retirement Income', formatAmount(monthlyIncome)],
    ['Withdrawal Rate', `${effectiveWithdrawalRate.toFixed(1)}%`],
  ];
  
  // Add financial summary table
  yPos = addFinancialTable(pdf, financialData, yPos, margin, colWidth, 'Key Financial Projections', 'primary');
  
  // Column 2: Timeline Information
  const timelineStartY = yPos;
  pdf.setFontSize(14);
  pdf.setTextColor(70, 70, 70);
  pdf.text('Timeline Highlights', margin + colWidth + 10, timelineStartY);
  
  // Create timeline table
  const timelineData = [
    ['Current Age', `${currentAge} years`],
    ['Retirement Age', `${retirementAge} years`],
    ['Years Until Retirement', `${yearsToRetirement} years`],
    ['Years In Retirement', `${yearsInRetirement} years`],
    ['Projected End Age', `${expectedEndAge} years`],
  ];
  
  // Add timeline table
  yPos = addFinancialTable(pdf, timelineData, yPos, margin + colWidth + 10, colWidth, 'Timeline Highlights', 'data');
  
  // Get the maximum Y position from both tables
  const financial_finalY = (pdf as any).lastAutoTable.finalY;
  yPos = financial_finalY + 10;
  
  // Risk Assessment Box
  pdf.setFillColor(isAtRisk ? 255 : 240, isAtRisk ? 240 : 250, isAtRisk ? 240 : 240);
  pdf.setDrawColor(isAtRisk ? 180 : 100, isAtRisk ? 60 : 160, isAtRisk ? 60 : 100);
  pdf.setLineWidth(0.5);
  pdf.roundedRect(margin, yPos, contentWidth, 20, 3, 3, 'FD');
  
  // Risk Title
  pdf.setFontSize(12);
  pdf.setTextColor(isAtRisk ? 180 : 60, isAtRisk ? 60 : 120, isAtRisk ? 60 : 60);
  pdf.text('Risk Assessment:', margin + 5, yPos + 7);
  
  // Risk Message
  pdf.setFontSize(10);
  const riskMessage = isAtRisk 
    ? 'Your withdrawal rate is higher than the recommended 4% rule, which may deplete your funds earlier than planned.'
    : 'Your withdrawal rate appears sustainable based on historical market data.';
  
  pdf.text(riskMessage, margin + 35, yPos + 7);
  
  yPos += 25;
  
  return yPos;
};

// Add results summary section to the PDF
const addResultsSummarySection = (
  pdf: jsPDF,
  params: SimulatorParams,
  statistics: ExtendedStatistics,
  formatAmount: (value: number) => string,
  margin: number,
  contentWidth: number,
  startY: number
): number => {
  let yPos = startY;
  
  // Use consistent section header
  yPos = addSectionHeader(
    pdf, 
    'Detailed Results Summary', 
    'Analysis of your retirement plan including savings growth and income projections.',
    margin,
    contentWidth,
    yPos
  );
  
  // Calculate key metrics
  const retirementAge = typeof params.retirementInput === 'string' 
    ? parseInt(params.retirementInput, 10) 
    : params.retirementInput;
  const retirementCapital = statistics.capitalAtRetirement || 0;
  const retirementYear = statistics.birthYear + retirementAge;
  
  // Calculate totals
  const totalInvested = params.initialCapital + (params.monthlyInvestment * 12 * (retirementAge - params.currentAge));
  const investmentGrowth = retirementCapital - totalInvested;
  const growthPercentage = totalInvested > 0 ? (investmentGrowth / totalInvested) * 100 : 0;
  
  // Find annual income in retirement
  let annualRetirementIncome = 0;
  if (params.withdrawalMode === 'amount') {
    annualRetirementIncome = params.monthlyRetirementWithdrawal * 12;
  } else if (params.withdrawalMode === 'rate' && params.withdrawalRate) {
    annualRetirementIncome = retirementCapital * (params.withdrawalRate / 100);
  } else {
    // Age-based withdrawal
    const yearsInRetirement = params.maxAge - retirementAge;
    const realReturnRate = (params.annualReturnRate - params.inflation) / 100;
    annualRetirementIncome = calculateSustainableWithdrawal(retirementCapital, realReturnRate, yearsInRetirement) * 12;
  }
  
  // Calculate inflation impact
  const inflationFactor = Math.pow(1 + params.inflation / 100, retirementAge - params.currentAge);
  const inflationAdjustedIncome = annualRetirementIncome / inflationFactor;
  
  // Setup grid layout
  const colWidth = contentWidth / 2 - 5;
  
  // Prepare savings growth data
  const savingsGrowthData = [
    ['Total Contributions', formatAmount(totalInvested)],
    ['Investment Growth', formatAmount(investmentGrowth)],
    ['Growth Percentage', `${growthPercentage.toFixed(1)}%`],
    ['Final Retirement Capital', formatAmount(retirementCapital)],
  ];
  
  // Prepare retirement income data
  const retirementIncomeData = [
    ['Annual Retirement Income', formatAmount(annualRetirementIncome)],
    ['Monthly Retirement Income', formatAmount(annualRetirementIncome / 12)],
    ['Income in Today\'s Dollars', formatAmount(inflationAdjustedIncome)],
    ['Retirement Year', `${retirementYear}`],
  ];
  
  // Create left column: Savings Growth
  pdf.setFontSize(14);
  pdf.setTextColor(70, 70, 70);
  pdf.text('Savings Growth', margin, yPos);
  yPos += 7;
  
  // Add savings growth table
  yPos = addFinancialTable(pdf, savingsGrowthData, yPos, margin, colWidth, 'Savings Growth', 'data');
  
  // Create right column: Retirement Income
  const incomeStartY = yPos;
  pdf.setFontSize(14);
  pdf.setTextColor(70, 70, 70);
  pdf.text('Retirement Income', margin + colWidth + 10, incomeStartY);
  
  // Add retirement income table
  yPos = addFinancialTable(pdf, retirementIncomeData, yPos, margin + colWidth + 10, colWidth, 'Retirement Income', 'data');
  
  // Get the maximum Y position from both tables
  const leftFinalY = (pdf as any).lastAutoTable.finalY;
  yPos = leftFinalY + 15;
  
  // Additional information box - key insights
  pdf.setFillColor(240, 248, 255); // Light blue background
  pdf.setDrawColor(100, 149, 237); // Cornflower blue border
  pdf.setLineWidth(0.5);
  pdf.roundedRect(margin, yPos, contentWidth, 25, 3, 3, 'FD');
  
  // Box title
  pdf.setFontSize(12);
  pdf.setTextColor(70, 130, 180); // Steel blue text
  pdf.text('Key Insights:', margin + 5, yPos + 7);
  
  // Insights content
  pdf.setFontSize(10);
  pdf.setTextColor(70, 70, 70);
  
  // Generate an insight based on the data
  let insightText = '';
  if (growthPercentage > 100) {
    insightText = `Your investments are projected to more than double by retirement, with ${growthPercentage.toFixed(0)}% growth above your contributions.`;
  } else if (statistics.yearFundsDeplete) {
    const yearsInRetirement = statistics.ageAtYear(statistics.yearFundsDeplete) - retirementAge;
    insightText = `Your funds are projected to last ${yearsInRetirement} years in retirement, depleting at age ${statistics.ageAtYear(statistics.yearFundsDeplete)}.`;
  } else {
    insightText = `Your retirement plan is designed to provide sustainable income throughout your retirement years.`;
  }
  
  pdf.text(insightText, margin + 35, yPos + 7);
  
  // Add context about inflation impact
  pdf.text(`Note: Due to inflation of ${params.inflation}%, your retirement income will be worth ${(100/inflationFactor).toFixed(1)}% of today's dollars.`, margin + 5, yPos + 18);
  
  yPos += 35;
  
  return yPos;
};

// Add chart section to the PDF
const addChartSection = async (
  pdf: jsPDF,
  chartRef: React.RefObject<HTMLDivElement>,
  margin: number,
  contentWidth: number,
  startY: number
): Promise<number> => {
  let yPos = startY;
  
  // Use consistent section header
  yPos = addSectionHeader(
    pdf,
    'Capital Projection Chart',
    'Visual projection of your retirement capital over time.',
    margin,
    contentWidth,
    yPos
  );
  
  if (chartRef.current) {
    console.log('chartRef.current exists', {
      width: chartRef.current.offsetWidth,
      height: chartRef.current.offsetHeight,
      children: chartRef.current.children.length,
      innerHTML: chartRef.current.innerHTML.substring(0, 100) + '...' // log first 100 chars
    });
    
    try {
      console.log('Starting html2canvas capture');
      // Capture the chart as canvas using html2canvas
      const canvas = await html2canvas(chartRef.current, {
        scale: 2, // Increase scale for better quality
        backgroundColor: '#FFFFFF',
        logging: true, // Enable logging
        onclone: (document, element) => {
          console.log('html2canvas cloned the element', {
            clonedElementWidth: element.offsetWidth,
            clonedElementHeight: element.offsetHeight,
            clonedElementChildren: element.children.length
          });
          return element;
        }
      });
      
      console.log('html2canvas completed successfully', {
        canvasWidth: canvas.width,
        canvasHeight: canvas.height
      });
      
      // Calculate dimensions to fit within content width
      const imgWidth = contentWidth;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      
      // Add chart image to PDF
      const imgData = canvas.toDataURL('image/png');
      console.log('Generated image data URL of length:', imgData.length);
      
      pdf.addImage(imgData, 'PNG', margin, yPos, imgWidth, imgHeight);
      console.log('Added image to PDF');
      
      yPos += imgHeight + 15;
    } catch (error) {
      console.error('Error capturing chart:', error);
      
      // Add error message if chart capture fails
      pdf.setFontSize(10);
      pdf.setTextColor(180, 60, 60);
      pdf.text('Chart could not be generated. Please try again.', margin, yPos);
      yPos += 10;
    }
  } else {
    console.log('chartRef.current is null or undefined');
    pdf.setFontSize(10);
    pdf.setTextColor(180, 60, 60);
    pdf.text('Chart reference not available.', margin, yPos);
    yPos += 10;
  }
  
  return yPos;
};

// Add analyses and optimization section to the PDF
const addAnalysesSection = (
  pdf: jsPDF,
  params: SimulatorParams,
  statistics: ExtendedStatistics,
  formatAmount: (value: number) => string,
  margin: number,
  contentWidth: number,
  startY: number,
  providedAnalyses?: AnalysesData
): number => {
  let yPos = startY;
  
  // Use consistent section header
  yPos = addSectionHeader(
    pdf,
    'Retirement Optimization Strategies',
    'Analysis of potential improvements to strengthen your retirement plan.',
    margin,
    contentWidth,
    yPos
  );
  
  // Use provided analyses data if available, otherwise calculate it
  let analyses: AnalysesData = providedAnalyses || (() => {
    // Calculate analyses data similar to the Analyses component
    // 1. Investment increase analysis
    const investmentIncrease = params.monthlyInvestment * 0.2; // Suggest 20% increase
    const additionalCapital = investmentIncrease * 12 * (statistics.retirementStartAge - params.currentAge);
    const estimatedAdditionalReturns = additionalCapital * (statistics.capitalAtRetirement / statistics.totalInvestedAmount - 1);
    const totalBenefit = additionalCapital + estimatedAdditionalReturns;
    
    // 2. Calculate impact of delaying retirement
    const yearDelayImpact = params.monthlyInvestment * 12 + 
      (statistics.capitalAtRetirement * (params.annualReturnRate / 100));
    
    // 3. Calculate withdrawal reduction impact
    const withdrawalReduction = params.monthlyRetirementWithdrawal * 0.1; // 10% reduction
    const withdrawalYears = statistics.retirementDuration || 20; // Fallback if not available
    const withdrawalSavings = withdrawalReduction * 12 * withdrawalYears;
    
    // 4. Calculate return improvement impact
    const returnImprovement = 0.5; // 0.5% improvement
    const improvedReturn = statistics.totalInvestedAmount * (1 + (params.annualReturnRate + returnImprovement) / 100) ** (statistics.retirementStartAge - params.currentAge);
    const returnBenefit = improvedReturn - statistics.capitalAtRetirement;
    
    // 5. Calculate risk of running out analysis
    const isCapitalExhausted = statistics.isCapitalExhausted || statistics.finalCapital <= 0;
    const yearsRemaining = isCapitalExhausted ? 0 : 
      Math.floor(statistics.finalCapital / (params.monthlyRetirementWithdrawal * 12));
    
    // Calculate safety margin with proper handling of potentially undefined properties
    const lifeExpectancy = statistics.lifeExpectancy || 90;
    const exhaustionAge = statistics.exhaustionAge || 80;
    const safetyMargin = isCapitalExhausted ? 
      -Math.floor((lifeExpectancy - exhaustionAge) / 5) * 5 : 
      Math.floor(yearsRemaining / 5) * 5;
    
    const riskLevel = isCapitalExhausted ? 'High' : 
                     (statistics.finalCapital / statistics.capitalAtRetirement < 0.3 ? 'Medium' : 'Low');
    
    // Generate recommended changes
    const needsSignificantChanges = riskLevel === 'High' || riskLevel === 'Medium';
    const recommendedChanges: RecommendationItem[] = [];
    
    if (needsSignificantChanges) {
      if ((statistics.retirementStartAge - params.currentAge) > 5) {
        recommendedChanges.push({
          change: 'Increase monthly investment',
          impact: `+${Math.round(params.monthlyInvestment * 0.3)} ${params.currency}/month`,
          priority: 'High'
        });
      }
      
      recommendedChanges.push({
        change: 'Delay retirement',
        impact: `+${needsSignificantChanges ? 3 : 1} years`,
        priority: needsSignificantChanges ? 'High' : 'Medium'
      });
      
      recommendedChanges.push({
        change: 'Reduce withdrawal',
        impact: `-${Math.round(params.monthlyRetirementWithdrawal * 0.15)} ${params.currency}/month`,
        priority: 'Medium'
      });
    } else {
      recommendedChanges.push({
        change: 'Increase monthly investment',
        impact: `+${Math.round(params.monthlyInvestment * 0.1)} ${params.currency}/month`,
        priority: 'Medium'
      });
      
      recommendedChanges.push({
        change: 'Optimize investment returns',
        impact: `+${returnImprovement.toFixed(1)}% return rate`,
        priority: 'Medium'
      });
    }
    
    // Small adjustment always suggested for best practices
    recommendedChanges.push({
      change: 'Reduce investment fees',
      impact: 'Find lower cost options',
      priority: 'Low'
    });
    
    // Create analyses object with all the data
    return {
      investmentIncrease: {
        amount: investmentIncrease,
        additionalCapital,
        estimatedAdditionalReturns,
        totalBenefit
      },
      delayRetirement: {
        years: 2,
        impact: yearDelayImpact * 2,
        newCapital: statistics.capitalAtRetirement + yearDelayImpact * 2
      },
      withdrawalReduction: {
        amount: withdrawalReduction,
        totalSavings: withdrawalSavings,
        additionalYears: Math.floor(withdrawalSavings / (params.monthlyRetirementWithdrawal * 12))
      },
      returnImprovement: {
        percent: returnImprovement,
        benefit: returnBenefit,
        newCapital: statistics.capitalAtRetirement + returnBenefit
      },
      runningOut: {
        risk: riskLevel,
        safetyMargin,
      },
      recommendations: recommendedChanges
    };
  })();
  
  // Convert recommendations to table format
  const recommendedChangesTableData = analyses.recommendations.map((rec: RecommendationItem) => [
    rec.change,
    rec.impact,
    rec.priority
  ]);
  
  // Add recommended improvements table
  pdf.setFontSize(14);
  pdf.setTextColor(70, 70, 70);
  pdf.text('Recommended Improvements', margin, yPos);
  yPos += 7;
  
  // Add recommended improvements table with enhanced styling
  autoTable(pdf, {
    startY: yPos,
    head: [['Recommendation', 'Impact', 'Priority']],
    body: recommendedChangesTableData,
    margin: { left: margin, right: margin },
    headStyles: { 
      fillColor: COLORS.primary, 
      textColor: [255, 255, 255],
      fontStyle: 'bold',
      fontSize: 11
    },
    bodyStyles: { fontSize: 10 },
    columnStyles: {
      0: { cellWidth: contentWidth * 0.5 },
      1: { cellWidth: contentWidth * 0.3 },
      2: { cellWidth: contentWidth * 0.2 }
    },
    didDrawCell: (data) => {
      // Color the priority cell based on value
      if (data.column.index === 2 && data.row.index > 0) {
        const priority = data.cell.text[0];
        if (priority === 'High') {
          pdf.setFillColor(255, 235, 235);
          pdf.rect(data.cell.x, data.cell.y, data.cell.width, data.cell.height, 'F');
          pdf.setTextColor(COLORS.danger[0], COLORS.danger[1], COLORS.danger[2]);
        } else if (priority === 'Medium') {
          pdf.setFillColor(255, 248, 225);
          pdf.rect(data.cell.x, data.cell.y, data.cell.width, data.cell.height, 'F');
          pdf.setTextColor(COLORS.warning[0], COLORS.warning[1], COLORS.warning[2]);
        } else {
          pdf.setFillColor(235, 245, 255);
          pdf.rect(data.cell.x, data.cell.y, data.cell.width, data.cell.height, 'F');
          pdf.setTextColor(60, 120, 180);
        }
      }
    }
  });
  
  yPos = (pdf as any).lastAutoTable.finalY + 15;
  
  // Create 2-column layout for impact analyses
  const colWidth = contentWidth / 2 - 5;
  
  // Left column: Investment Increase Analysis
  pdf.setFontSize(14);
  pdf.setTextColor(70, 70, 70);
  pdf.text('Investment Increase Impact', margin, yPos);
  yPos += 7;
  
  // Investment increase data table
  const investmentData = [
    ['Monthly Increase', formatAmount(analyses.investmentIncrease.amount)],
    ['Additional Contributions', formatAmount(analyses.investmentIncrease.additionalCapital)],
    ['Additional Returns', formatAmount(analyses.investmentIncrease.estimatedAdditionalReturns)],
    ['Total Benefit', formatAmount(analyses.investmentIncrease.totalBenefit)]
  ];
  
  autoTable(pdf, {
    startY: yPos,
    body: investmentData,
    margin: { left: margin, right: margin + contentWidth/2 + 5 },
    tableWidth: colWidth,
    theme: 'grid',
    headStyles: { fillColor: [63, 81, 181], textColor: [255, 255, 255] },
    bodyStyles: { fontSize: 10 },
    alternateRowStyles: { fillColor: [240, 250, 240] }
  });
  
  // Right column: Delaying Retirement Impact
  const delayRetirementY = yPos;
  pdf.setFontSize(14);
  pdf.setTextColor(70, 70, 70);
  pdf.text('Delaying Retirement Impact', margin + colWidth + 10, delayRetirementY);
  
  // Delay retirement data
  const delayRetirementData = [
    ['Delay Period', `${analyses.delayRetirement.years} years`],
    ['Additional Capital', formatAmount(analyses.delayRetirement.impact)],
    ['New Retirement Capital', formatAmount(analyses.delayRetirement.newCapital)],
    ['New Retirement Age', `${statistics.retirementStartAge + analyses.delayRetirement.years} years`]
  ];
  
  autoTable(pdf, {
    startY: delayRetirementY + 7,
    body: delayRetirementData,
    margin: { left: margin + colWidth + 10, right: margin },
    tableWidth: colWidth,
    theme: 'grid',
    headStyles: { fillColor: [63, 81, 181], textColor: [255, 255, 255] },
    bodyStyles: { fontSize: 10 },
    alternateRowStyles: { fillColor: [240, 240, 250] }
  });
  
  // Get the maximum Y position from both tables
  const maxTableY = (pdf as any).lastAutoTable.finalY;
  yPos = maxTableY + 15;
  
  // Add risk assessment box
  const riskLevel = analyses.runningOut.risk;
  pdf.setFillColor(riskLevel === 'High' ? 255 : (riskLevel === 'Medium' ? 255 : 240), 
                  riskLevel === 'High' ? 235 : (riskLevel === 'Medium' ? 248 : 250), 
                  riskLevel === 'High' ? 235 : (riskLevel === 'Medium' ? 225 : 240));
  pdf.setDrawColor(riskLevel === 'High' ? 180 : (riskLevel === 'Medium' ? 200 : 100), 
                  riskLevel === 'High' ? 60 : (riskLevel === 'Medium' ? 150 : 160), 
                  riskLevel === 'High' ? 60 : (riskLevel === 'Medium' ? 0 : 100));
  pdf.setLineWidth(0.5);
  pdf.roundedRect(margin, yPos, contentWidth, 20, 3, 3, 'FD');
  
  // Risk Title
  pdf.setFontSize(12);
  pdf.setTextColor(riskLevel === 'High' ? 180 : (riskLevel === 'Medium' ? 150 : 60), 
                  riskLevel === 'High' ? 60 : (riskLevel === 'Medium' ? 100 : 120), 
                  riskLevel === 'High' ? 60 : (riskLevel === 'Medium' ? 0 : 60));
  pdf.text('Risk of Outliving Your Money:', margin + 5, yPos + 7);
  
  // Risk Message
  pdf.setFontSize(10);
  let riskMessage = '';
  if (riskLevel === 'High') {
    riskMessage = 'Your capital is projected to run out before your life expectancy. Consider implementing multiple strategies above.';
  } else if (riskLevel === 'Medium') {
    riskMessage = 'Your plan has limited safety margin. Consider at least one optimization strategy to increase security.';
  } else {
    riskMessage = 'Your plan appears robust with sufficient safety margin, but optimization can still provide more flexibility.';
  }
  
  pdf.text(`${riskLevel} - ${riskMessage}`, margin + 60, yPos + 7);
  
  yPos += 25;
  
  // Add additional strategies section
  pdf.setFontSize(14);
  pdf.setTextColor(70, 70, 70);
  pdf.text('Additional Strategies', margin, yPos);
  yPos += 7;
  
  // Additional strategies table
  const additionalStrategies = [
    ['Withdrawal Reduction', `Reducing monthly withdrawal by ${formatAmount(analyses.withdrawalReduction.amount)} would extend your retirement by approximately ${analyses.withdrawalReduction.additionalYears} years.`],
    ['Return Optimization', `A ${analyses.returnImprovement.percent.toFixed(1)}% improvement in return rate could add ${formatAmount(analyses.returnImprovement.benefit)} to your retirement capital.`],
    ['Tax Optimization', 'Strategic use of tax-advantaged accounts can significantly increase your after-tax returns.'],
    ['Inflation Protection', `Your plan accounts for ${params.inflation.toFixed(1)}% inflation. Consider assets that hedge against higher inflation.`]
  ];
  
  autoTable(pdf, {
    startY: yPos,
    body: additionalStrategies,
    margin: { left: margin, right: margin },
    headStyles: { fillColor: [63, 81, 181], textColor: [255, 255, 255] },
    bodyStyles: { fontSize: 10 },
    alternateRowStyles: { fillColor: [245, 245, 250] },
  });
  
  yPos = (pdf as any).lastAutoTable.finalY + 10;
  
  return yPos;
};

// Add detailed schedule section to the PDF
const addScheduleSection = (
  pdf: jsPDF,
  formatAmount: (value: number) => string,
  margin: number,
  contentWidth: number,
  startY: number,
  scheduleData?: GraphDataPoint[]
): number => {
  let yPos = startY;
  
  // Use consistent section header
  yPos = addSectionHeader(
    pdf,
    'Detailed Schedule Projection',
    'Year-by-year breakdown of your retirement financial plan.',
    margin,
    contentWidth,
    yPos
  );
  
  // Check if we have data
  if (!scheduleData || scheduleData.length === 0) {
    pdf.setFontSize(11);
    pdf.setTextColor(150, 150, 150);
    pdf.text('No detailed schedule data available.', margin, yPos);
    return yPos + 10;
  }
  
  // Determine if we need to paginate the table
  // We'll show up to 30 rows per page to keep it readable
  const rowsPerPage = 30;
  const totalPages = Math.ceil(scheduleData.length / rowsPerPage);
  
  // Process schedule data in pages
  for (let pageNum = 0; pageNum < totalPages; pageNum++) {
    // We only add a page break after the first page
    if (pageNum > 0) {
      pdf.addPage();
      yPos = margin;
      
      // Add a page header for continuation pages
      pdf.setFontSize(14);
      pdf.setTextColor(63, 81, 181);
      pdf.text(`Detailed Schedule Projection (continued - ${pageNum+1}/${totalPages})`, margin, yPos);
      yPos += 10;
    }
    
    // Calculate the slice of data for this page
    const startIdx = pageNum * rowsPerPage;
    const endIdx = Math.min(startIdx + rowsPerPage, scheduleData.length);
    const pageData = scheduleData.slice(startIdx, endIdx);
    
    // Prepare table data
    const tableHeaders = ['Year', 'Age', 'Capital', 'Variation', 'Interest', 'Inv/With', 'Phase'];
    
    // Convert the GraphDataPoint objects to arrays for the table
    const tableRows = pageData.map(entry => [
      entry.year.toString(),
      entry.age.toString(),
      formatAmount(entry.capital),
      (entry.variation >= 0 ? '+' : '') + formatAmount(entry.variation),
      '+' + formatAmount(entry.annualInterest),
      (entry.netVariationExcludingInterest >= 0 ? '+' : '') + formatAmount(entry.netVariationExcludingInterest),
      entry.retirement === "Yes" ? "Retirement" : "Investment"
    ]);
    
    // Add the table with enhanced styling
    const tableOptions = {
      startY: yPos,
      head: [tableHeaders],
      body: tableRows,
      margin: { left: margin, right: margin },
      columnStyles: {
        0: { cellWidth: contentWidth * 0.1 }, // Year
        1: { cellWidth: contentWidth * 0.08 }, // Age
        2: { cellWidth: contentWidth * 0.2 }, // Capital
        3: { cellWidth: contentWidth * 0.15 }, // Variation
        4: { cellWidth: contentWidth * 0.15 }, // Interest
        5: { cellWidth: contentWidth * 0.15 }, // Inv/With
        6: { cellWidth: contentWidth * 0.17 } // Phase
      },
      didParseCell: (data: any) => {
        // Color the retirement phase rows
        if (data.section === 'body') {
          const rowIndex = data.row.index;
          const phaseValue = tableRows[rowIndex][6];
          const capitalValue = parseFloat(tableRows[rowIndex][2].replace(/[^0-9.-]+/g, ''));
          
          // Highlight years where capital is zero or negative
          if (capitalValue <= 0) {
            data.cell.styles.fillColor = [255, 220, 220]; // Light red for depleted capital
          } else if (phaseValue === "Retirement") {
            data.cell.styles.fillColor = [250, 240, 255];
          } else if (rowIndex % 2 === 1) {
            // Alternate row color for investment phase
            data.cell.styles.fillColor = [245, 245, 255];
          }
        }
        
        // Color the variation and investment/withdrawal cells
        if (data.section === 'body') {
          const columnIndex = data.column.index;
          const cellValue = data.cell.text[0] as string;
          
          if (columnIndex === 3 && cellValue.startsWith('+')) {
            data.cell.styles.textColor = COLORS.success; // Green for positive variation
          } else if (columnIndex === 3) {
            data.cell.styles.textColor = COLORS.danger; // Red for negative variation
          } else if (columnIndex === 4) {
            data.cell.styles.textColor = [100, 100, 200]; // Blue for interest
          } else if (columnIndex === 5 && cellValue.startsWith('+')) {
            data.cell.styles.textColor = [0, 100, 150]; // Blue for investment
          } else if (columnIndex === 5) {
            data.cell.styles.textColor = [180, 0, 50]; // Red for withdrawal
          }
        }
      }
    };
    
    // Apply consistent styling with compact format
    applyTableStyle(tableOptions, 'compact');
    
    // Draw the table
    autoTable(pdf, tableOptions);
    
    yPos = (pdf as any).lastAutoTable.finalY + 10;
  }
  
  // Add a note about the schedule data
  pdf.setFontSize(9);
  pdf.setTextColor(100, 100, 100);
  pdf.text(`The schedule includes ${scheduleData.length} years of projected data.`, margin, yPos);
  
  return yPos + 10;
};

// Add parameters section to the PDF - Redesigned to be more compact
const addParametersSection = (
  pdf: jsPDF,
  params: SimulatorParams,
  formatAmount: (value: number) => string,
  margin: number,
  contentWidth: number,
  startY: number
): number => {
  let yPos = startY;
  
  // Use consistent section header
  yPos = addSectionHeader(
    pdf,
    'Plan Parameters',
    'The detailed parameters used for your retirement plan calculations.',
    margin,
    contentWidth,
    yPos
  );
  
  // Create comprehensive parameters table with all data in a single, condensed table
  const paramsData = [
    // Current Status
    ['Initial Capital', formatAmount(params.initialCapital)],
    ['Current Age', `${params.currentAge} years`],
    ['Monthly Investment', formatAmount(params.monthlyInvestment)],
    
    // Retirement Plan
    ['Retirement Age', `${params.retirementInput} years`],
  ];
  
  // Add withdrawal strategy info based on mode
  if (params.withdrawalMode === 'amount') {
    paramsData.push(['Monthly Withdrawal', formatAmount(params.monthlyRetirementWithdrawal)]);
  } else if (params.withdrawalMode === 'rate') {
    paramsData.push(['Withdrawal Rate', `${params.withdrawalRate}%`]);
  } else {
    paramsData.push(['Target End Age', `${params.maxAge} years`]);
  }
  
  // Market Assumptions
  paramsData.push(
    ['Annual Return Rate', `${params.annualReturnRate}%`],
    ['Inflation Rate', `${params.inflation}%`],
    ['Compound Frequency', params.compoundFrequency === 'monthly' ? 'Monthly' : 'Annual'],
    ['Real Return Rate', `${(params.annualReturnRate - params.inflation).toFixed(1)}%`]
  );
  
  // Add parameters table - two column layout
  autoTable(pdf, {
    startY: yPos,
    head: [['Parameter', 'Value']],
    body: paramsData,
    margin: { left: margin, right: margin },
    headStyles: { fillColor: [63, 81, 181], textColor: [255, 255, 255] },
    alternateRowStyles: { fillColor: [240, 240, 255] },
    styles: { fontSize: 10, cellPadding: 2 }, // Reduced padding for compactness
  });
  
  yPos = (pdf as any).lastAutoTable.finalY + 10;
  
  return yPos;
};

